const left = () => morse.$$("div.board input[type=checkbox]").filter(c => !c.checked).length;
const paint = () => morse.$$(".tasks-left").forEach(b => { b.textContent = left() + " left"; });

morse.watch("#root > header.hdr", hdr => {
  if (hdr.querySelector(".tasks-left")) return;
  const badge = morse.el("span", { class: "tasks-left" });
  const title = morse.byText("#root > header.hdr *", "Sprint 42");
  if (title) title.after(badge); else hdr.appendChild(badge);
  paint();
});

morse.on(document, "change", paint);
morse.every(1000, paint);

