morse.watch("#root > div.board", board => {
  const count = [...board.querySelectorAll("article.card")]
    .filter(c => !c.querySelector("input[type=checkbox]")?.checked).length;
  const title = morse.$("#root > header.hdr > *:first-child");
  if (title) title.dataset.left = count;
}, { live: true });

morse.every(300, () => {
  const hdr = morse.$("#root > header.hdr");
  if (!hdr) return;
  let badge = hdr.querySelector(":scope > .tasks-left");
  if (!badge) {
    badge = morse.el("span", {
      class: "tasks-left",
      style: "margin-left:12px;padding:2px 10px;border-radius:999px;font-size:13px;font-weight:500;background:rgba(0,0,0,0.07);color:currentColor;white-space:nowrap;align-self:center"
    });
    hdr.insertBefore(badge, hdr.querySelector("button.add"));
  }
  const left = morse.$$("div.board input[type=checkbox]").filter(c => !c.checked).length;
  const text = left + " left";
  if (badge.textContent !== text) badge.textContent = text;
});

