results.js:
function sortByPrice() {
  const grid = morse.$("#__next > div:nth-of-type(2) > main > div:nth-of-type(2)");
  if (!grid) return;
  const priceOf = el => {
    const m = el.textContent.match(/\$\s?([\d,]+(?:\.\d+)?)/);
    return m ? parseFloat(m[1].replace(/,/g, "")) : Infinity;
  };
  Array.from(grid.children)
    .map(el => ({ el, p: priceOf(el) }))
    .sort((a, b) => a.p - b.p)
    .forEach(x => grid.appendChild(x.el));
  morse.toast("Sorted by price, lowest first");
}

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", bar => {
  if (bar.querySelector(".morse-sort-btn")) return;
  bar.appendChild(morse.el("button", {
    class: "morse-sort-btn",
    text: "Sort by price: low to high",
    on: { click: sortByPrice }
  }));
});

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", bar => {
  if (bar.querySelector("[data-morse-sort]")) return;

  const priceOf = card => {
    const m = (card.textContent || "").match(/\$\s?([\d,]+(?:\.\d+)?)/);
    return m ? parseFloat(m[1].replace(/,/g, "")) : Infinity;
  };

  let original = null;
  let sorted = false;

  const btn = morse.el("button", {
    type: "button",
    "data-morse-sort": "",
    text: "Sort: price low to high",
    style: "margin-left:auto;font:inherit;font-size:14px;color:inherit;background:transparent;border:1px solid currentColor;border-radius:6px;padding:4px 10px;cursor:pointer;",
    on: {
      click: () => {
        const grid = morse.$("#__next > div:nth-of-type(2) > main > div:nth-of-type(2)");
        if (!grid) return;
        if (!original) original = [...grid.children];

        if (sorted) {
          original.forEach(card => grid.appendChild(card));
          btn.textContent = "Sort: price low to high";
        } else {
          [...grid.children]
            .sort((a, b) => priceOf(a) - priceOf(b))
            .forEach(card => grid.appendChild(card));
          btn.textContent = "Sort: default order";
        }
        sorted = !sorted;
      }
    }
  });

  bar.appendChild(btn);
});

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", header => {
  const grid = header.nextElementSibling;
  const priceOf = el => {
    const m = (el.textContent || "").match(/\$(\d+(?:\.\d+)?)/);
    return m ? parseFloat(m[1]) : Infinity;
  };
  const btn = morse.el("button", {
    text: "Sort by price",
    type: "button",
    style: "margin-left:auto;font:inherit;font-size:14px;color:inherit;background:none;border:1px solid currentColor;border-radius:6px;padding:4px 10px;cursor:pointer;opacity:0.8",
    on: {
      click: () => {
        const items = [...grid.children];
        items.sort((a, b) => priceOf(a) - priceOf(b));
        items.forEach(item => grid.appendChild(item));
      }
    }
  });
  header.appendChild(btn);
});
